+export function DarkModeToggle() {
+  const [dark, setDark] = useState(() => localStorage.getItem('theme') === 'dark');
+  useEffect(() => { document.body.classList.toggle('dark', dark); localStorage.setItem('theme', dark ? 'dark' : 'light'); }, [dark]);
+  return <button onClick={() => setDark(d => !d)}>{dark ? 'Light' : 'Dark'} mode</button>;
+}

+import { test, expect } from '@playwright/test';
+test.describe('Dashboard', () => {
+  test.beforeEach(async ({ page }) => { await page.goto('/dashboard'); });
+  test('shows deck count', async ({ page }) => { await expect(page.locator('.deck-count')).toBeVisible(); });
+  test('search filters results', async ({ page }) => { await page.fill('.search', 'math'); await expect(page.locator('.deck-card')).toHaveCount(2); });
+  test('create deck button opens modal', async ({ page }) => { await page.click('button:has-text(\New Deck")'); await expect(page.locator('.modal')).toBeVisible(); });
+});"

