+const io = new Server(httpServer, { cors: { origin: process.env.CLIENT_URL } });
+io.on('connection', socket => {
+  socket.on('join-deck', (deckId) => socket.join(`deck:${deckId}`));
+});
+export function broadcastCardUpdate(deckId: number, card: Card) {
+  io.to(`deck:${deckId}`).emit('card-updated', card);
+}

+router.get('/decks/:id/export/anki', async (req, res) => {
+  const cards = await CardService.listByDeck(req.params.id);
+  const pkg = AnkiPackage.create(cards.map(c => ({ front: c.front, back: c.back })));
+  res.setHeader('Content-Disposition', `attachment; filename=deck-${req.params.id}.apkg`);
+  res.send(await pkg.toBuffer());
+});
